  * for dashboard sparklines. The caller passes a single SELECT returning a
  * bucket column + one column per stat; this hook returns the tabular result
  * and a helper to pivot it into a `number[]` series per stat column.
  *
  * The endpoint is org-scoped (the server injects `$1 = organization_id`),
  * so callers only need to know the org slug.
  */

 import { useQuery } from "@tanstack/react-query";
 import { apiCall } from "./core";

 export interface MetricSeriesResult {
 	columns: string[];
 	rows: unknown[][];
 }

 export interface MetricSeries {
 	result: MetricSeriesResult | undefined;
 	column: (name: string) => number[];
 }

 /**
  * Stable hash for the cache key — keeps two callers with the same SQL on
  * the same react-query entry without serializing the entire string into
  * the key.
  */
 function hashSql(sql: string): string {
 	let h = 0;
 	for (let i = 0; i < sql.length; i++) {
 		h = (h << 5) - h + sql.charCodeAt(i);
 		h |= 0;
 	}
 	return h.toString(36);
 }

 function metricSeriesQueryOptions(orgSlug: string, sql: string) {
 	return {
 		queryKey: ["metric_series", orgSlug, hashSql(sql)] as const,
 		queryFn: () =>
 			apiCall<MetricSeriesResult>("metric_series", { sql }, { slug: orgSlug }),
 		staleTime: 60_000,
 	};
 }

 export function useMetricSeries(
 	orgSlug: string | null | undefined,
 	sql: string | null | undefined,
 ) {
 	const enabled = !!orgSlug && !!sql;
 	const opts = metricSeriesQueryOptions(orgSlug ?? "", sql ?? "");
 	return useQuery<MetricSeriesResult>({ ...opts, enabled });
 }

 useMetricSeries.queryOptions = (orgSlug: string, sql: string) =>
 	metricSeriesQueryOptions(orgSlug, sql);

 /** Pivot a tabular result into `number[]` for a named column. */
 export function pickSeries(
 	result: MetricSeriesResult | undefined,
 	column: string,
 ): number[] {
 	// Defend against malformed responses (mock fixtures, partial cache hits)
 	// — a missing `columns` key should be treated the same as "no data".
 	if (!result?.columns?.length || !result.rows) return [];
 	const idx = result.columns.indexOf(column);
 	if (idx < 0) return [];
 	return result.rows.map((r) => Number(r[idx]) || 0);
 }

 const SAFE_KEY = /^[a-z][a-z0-9_]*$/;

 /**
  * Build a 14-day cumulative-counts SQL over lifecycle change events.
  *
  * Pass a map of `{ outputColumnName: entityTypeSlug }`. Each entity type is
  * pivoted into a `COUNT FILTER` per op (created/deleted) and the cumulative
  * net is exposed as `outputColumnName`. Keys must match `[a-z][a-z0-9_]*`
  * (validated server-side anyway, but we reject early for clean errors).
  *
  * Example — produces columns `bucket, agents, users, behaviors`:
- *   lifecycleCumulativeStatsSql({ agents: 'agent', users: 'member', behaviors: 'behavior' })
+ *   lifecycleCumulativeStatsSql({ agents: 'agent', users: 'member', behaviors: 'watcher' })
  */
 export function lifecycleCumulativeStatsSql(
 	stats: Record<string, string>,
 ): string {
 	const entries = Object.entries(stats);
 	for (const [col, type] of entries) {
 		if (!SAFE_KEY.test(col)) {
 			throw new Error(`lifecycleCumulativeStatsSql: unsafe column name '${col}'`);
 		}
 		if (!SAFE_KEY.test(type)) {
 			throw new Error(`lifecycleCumulativeStatsSql: unsafe entity_type '${type}'`);
 		}
 	}

 	const bucketCols = entries
 		.flatMap(([col, type]) => [
 			`COUNT(*) FILTER (
         WHERE semantic_type = 'change'
           AND metadata->>'category' = 'lifecycle'
           AND metadata->>'entity_type' = '${type}'
           AND metadata->>'op' = 'created'
       ) AS ${col}_added`,
 			`COUNT(*) FILTER (
         WHERE semantic_type = 'change'
           AND metadata->>'category' = 'lifecycle'
           AND metadata->>'entity_type' = '${type}'
           AND metadata->>'op' = 'deleted'
       ) AS ${col}_removed`,
 		])
 		.join(",\n    ");

 	const selectCols = entries
 		.map(
 			([col]) =>
 				`  SUM(COALESCE(b.${col}_added, 0) - COALESCE(b.${col}_removed, 0))
     OVER (ORDER BY d.bucket) AS ${col}`,
 		)
 		.join(",\n");

 	return `
 WITH days AS (
   SELECT generate_series(
     date_trunc('day', now() - interval '13 days'),
     date_trunc('day', now()),
     interval '1 day'
   ) AS bucket
 ),
 buckets AS (
   SELECT
     date_trunc('day', created_at) AS bucket,
     ${bucketCols}
   FROM events
   WHERE created_at > now() - interval '14 days'
   GROUP BY 1
 )
 SELECT d.bucket,
 ${selectCols}
 FROM days d
 LEFT JOIN buckets b ON b.bucket = d.bucket
 ORDER BY d.bucket
 `;
 }
