                 listTask, countTask, runsTask, connectionsTask, behaviorsTask
             )
             notifications = list.notifications
             unreadCount = count
             recentRuns = runs.runs
             connections = conns.connections
             // Goals filter is best-effort and scoped to its own try/catch:
