type EntityFieldChangeDetails = {
	fields: Record<string, unknown>;
	current: Record<string, unknown>;
	reason?: string;
	watcherId?: string;
	watcherName?: string;
	watcherAgentId?: string;
	entityType?: string;
	entityName?: string;
	entitySlug?: string;
	parentSlug?: string;
	parentEntityType?: string;
	/** Who proposed the change — 'agent' or 'behavior'. Drives the header wording. */
	attribution?: string;
	/**
	 * The verified principal that asked for this change (`runs.initiator_kind` /
	 * `initiator_ref`, copied onto the card). More specific than `attribution`,
	 * which only distinguishes behavior from agent — this names the actual agent
	 * and client. Absent on proposals made before provenance was recorded.
	 */
	initiator?: RunInitiator;
};

/** Card-side view of a run's initiator. Mirrors the server's `initiatorRef`. */
type RunInitiator = {
	kind?: string;
	agent_id?: string;
	client_id?: string;
	user_id?: string;
	watcher_id?: number;
};

/**
 * How to name the proposer of a change. Prefers the recorded initiator; falls
 * back to `attribution`'s coarse behavior/agent split for older proposals,
 * which carry no initiator at all.
 */
function proposerLabelFor(
	initiator: RunInitiator | undefined,
	attribution: string | undefined,
	watcherId: string | undefined,
): string {
	if (initiator?.kind === "agent_session" && initiator.agent_id) {
		return initiator.client_id
			? `${initiator.agent_id} via ${initiator.client_id}`
			: initiator.agent_id;
	}
	if (initiator?.kind === "user") return "a person";
	if (attribution === "agent") return "an agent";
	return watcherId ? `Behavior ${watcherId}` : "a Behavior";
}

type MergeEvidence = { kind: string; identifier: string };
type MergeEntity = {
	key: string;
	name: string;
	/** Absent when the proposal carried names but no entity snapshot. */
	slug?: string;
	entityType?: string;
	/** Nested entities need their parent segment or the link 404s. */
	parentSlug?: string;
	parentEntityType?: string;
};

type MergeDetails = {
	winnerName?: string;
	winnerSlug?: string;
	winnerEntityType?: string;
	winnerParentSlug?: string;
	winnerParentEntityType?: string;
	losers: MergeEntity[];
	matchEvidence: MergeEvidence[];
	/**
	 * How the last re-check changed the evidence. Present only on a proposal the
	 * server re-checked and re-presented; a re-presented card is otherwise
	 * indistinguishable from the one the reviewer already clicked.
	 */
	evidenceChange?: { dropped: MergeEvidence[]; gained: MergeEvidence[] };
};

type EntityChangeDetails = Omit<
	EntityFieldChangeDetails,
	"fields" | "current"
> & {
	operation: "create" | "delete" | "merge";
	proposal: Record<string, unknown> | null;
	current: Record<string, unknown> | null;
	merge?: MergeDetails;
	proposerRationale?: string;
};

function formatFieldChangeAction(details: EntityFieldChangeDetails): string {
	const fields = Object.keys(details.fields);
	const fieldList = fields.map(formatLabel).join(", ") || "field";
	const fieldNoun = fields.length === 1 ? "field" : "fields";
	const entityLabel = details.entityType
		? formatLabel(details.entityType).toLowerCase()
		: "entity";
	return `Update ${entityLabel} ${fieldNoun}: ${fieldList}`;
}

function getEntityFieldChangeDetails(
	content: ContentItem,
	metadata: Record<string, unknown>,
): EntityFieldChangeDetails | null {
	const fields = asRecord(metadata.fields);
	if (!fields || Object.keys(fields).length === 0) return null;
	if (
		metadata.action_key !== "entity_field_change" &&
		metadata.tool !== "entity_field_change"
	) {
		return null;
	}

	const current = asRecord(metadata.current) ?? {};
	const contentWithEntity = content as ContentItem & {
		entity_name?: string | null;
	};
	return {
		fields,
		current,
		reason: typeof metadata.reason === "string" ? metadata.reason : undefined,
		watcherId:
			metadata.watcher_id != null ? String(metadata.watcher_id) : undefined,
		watcherName:
			typeof metadata.watcher_name === "string"
				? metadata.watcher_name
				: undefined,
		watcherAgentId:
			typeof metadata.watcher_agent_id === "string"
				? metadata.watcher_agent_id
				: undefined,
		entityType:
			typeof metadata.entity_type === "string"
				? metadata.entity_type
				: undefined,
		entityName:
			(typeof metadata.entity_name === "string"
				? metadata.entity_name
				: undefined) ??
			contentWithEntity.entity_name ??
			undefined,
		entitySlug:
			typeof metadata.entity_slug === "string"
				? metadata.entity_slug
				: undefined,
		parentSlug:
			typeof metadata.parent_slug === "string"
				? metadata.parent_slug
				: undefined,
		parentEntityType:
			typeof metadata.parent_entity_type === "string"
				? metadata.parent_entity_type
				: undefined,
		attribution:
			typeof metadata.attribution === "string"
				? metadata.attribution
				: undefined,
		initiator:
			metadata.initiator && typeof metadata.initiator === "object"
				? (metadata.initiator as RunInitiator)
				: undefined,
	};
}

function evidenceOf(proposal: Record<string, unknown> | null): MergeEvidence[] {
	if (!proposal || !Array.isArray(proposal.evidence)) return [];
	return proposal.evidence.flatMap((item) => {
		const evidence = asRecord(item);
		const kind = evidence?.kind;
		const identifier = evidence?.identifier;
		return typeof kind === "string" && typeof identifier === "string"
			? [{ kind, identifier }]
			: [];
	});
}

function evidenceListOf(value: unknown): MergeEvidence[] {
	if (!Array.isArray(value)) return [];
	return value.flatMap((item) => {
		const evidence = asRecord(item);
		const kind = evidence?.kind;
		const identifier = evidence?.identifier;
		return typeof kind === "string" && typeof identifier === "string"
			? [{ kind, identifier }]
			: [];
	});
}

function evidenceChangeOf(
	proposal: Record<string, unknown> | null,
): { dropped: MergeEvidence[]; gained: MergeEvidence[] } | undefined {
	const change = asRecord(proposal?.evidence_change);
	if (!change) return undefined;
	// A well-formed but empty delta still means "we re-checked this" and must
	// render; only a missing or unusable payload stays silent.
	if (!Array.isArray(change.dropped) || !Array.isArray(change.gained)) {
		return undefined;
	}
	return {
		dropped: evidenceListOf(change.dropped),
		gained: evidenceListOf(change.gained),
	};
}

function stringOrUndefined(value: unknown): string | undefined {
	return typeof value === "string" ? value : undefined;
}

function buildMergeDetails(metadata: Record<string, unknown>): MergeDetails {
	const current = asRecord(metadata.current);
	const proposal = asRecord(metadata.proposal);
	const winner = asRecord(current?.winner);
	const loser = asRecord(current?.loser);
	const duplicates = Array.isArray(current?.duplicates)
		? current.duplicates.map(asRecord)
		: [];
	const snapshotLosers =
		duplicates.length > 0 ? duplicates : loser ? [loser] : [];

	const losersFromSnapshot = snapshotLosers.flatMap((snapshot) => {
		const name = stringOrUndefined(snapshot?.name);
		const id = snapshot?.id;
		return name && (typeof id === "string" || typeof id === "number")
			? [
					{
						key: String(id),
						name,
						slug: stringOrUndefined(snapshot?.slug),
						entityType: stringOrUndefined(snapshot?.entity_type),
						parentSlug: stringOrUndefined(snapshot?.parent_slug),
						parentEntityType: stringOrUndefined(snapshot?.parent_entity_type),
					},
				]
			: [];
	});
	const proposalIds = Array.isArray(proposal?.entity_ids)
		? proposal.entity_ids
		: [];
	const losersFromProposal = Array.isArray(proposal?.names)
		? proposal.names.flatMap((name, index) => {
				const id = proposalIds[index];
				return typeof name === "string" &&
					(typeof id === "string" || typeof id === "number")
					? [{ key: String(id), name }]
					: [];
			})
		: [];
	const fallbackName = stringOrUndefined(proposal?.name);
	const fallbackId = proposal?.entity_id;

	const losers =
		losersFromSnapshot.length > 0
			? losersFromSnapshot
			: losersFromProposal.length > 0
				? losersFromProposal
				: fallbackName &&
						(typeof fallbackId === "string" || typeof fallbackId === "number")
					? [{ key: String(fallbackId), name: fallbackName }]
					: [];

	return {
		winnerName:
			stringOrUndefined(winner?.name) ??
			stringOrUndefined(proposal?.winner_name),
		winnerSlug: stringOrUndefined(winner?.slug),
		winnerEntityType: stringOrUndefined(winner?.entity_type),
		winnerParentSlug: stringOrUndefined(winner?.parent_slug),
		winnerParentEntityType: stringOrUndefined(winner?.parent_entity_type),
		losers,
		matchEvidence: evidenceOf(proposal),
		evidenceChange: evidenceChangeOf(proposal),
	};
}

/**
 * The card header stays short on merges — the Kept/Merged-away panel right
 * below already names both entities, so spelling them out again here is noise.
 * The name-rich "Merge X into Y" form lives server-side on the event title,
 * which is what timelines and notifications show without the panel.
 */
function formatEntityChangeAction(details: EntityChangeDetails): string {
	const entityLabel = details.entityType
		? formatLabel(details.entityType).toLowerCase()
		: "entity";
	if (details.operation === "merge") {
		const losers = details.merge?.losers ?? [];
		return losers.length > 1
			? `Merge ${losers.length} duplicate ${entityLabel}s`
			: `Merge duplicate ${entityLabel}`;
	}
	return `${formatLabel(details.operation)} ${entityLabel}`;
}

function getEntityChangeDetails(
	content: ContentItem,
	metadata: Record<string, unknown>,
): EntityChangeDetails | null {
	if (
		metadata.action_key !== "entity_change" &&
		metadata.tool !== "entity_change"
	) {
		return null;
	}
	const operation = metadata.action;
	if (
		operation !== "create" &&
		operation !== "delete" &&
		operation !== "merge"
	) {
		return null;
	}
	const contentWithEntity = content as ContentItem & {
		entity_name?: string | null;
	};
	return {
		operation,
		merge: operation === "merge" ? buildMergeDetails(metadata) : undefined,
		proposal: asRecord(metadata.proposal),
		current: asRecord(metadata.current),
		reason: typeof metadata.reason === "string" ? metadata.reason : undefined,
		watcherId:
			metadata.watcher_id != null ? String(metadata.watcher_id) : undefined,
		watcherName:
			typeof metadata.watcher_name === "string"
				? metadata.watcher_name
				: undefined,
		watcherAgentId:
			typeof metadata.watcher_agent_id === "string"
				? metadata.watcher_agent_id
				: undefined,
		entityType:
			typeof metadata.entity_type === "string"
				? metadata.entity_type
				: undefined,
		entityName:
			(typeof metadata.entity_name === "string"
				? metadata.entity_name
				: undefined) ??
			contentWithEntity.entity_name ??
			undefined,
		entitySlug:
			typeof metadata.entity_slug === "string"
				? metadata.entity_slug
				: undefined,
		parentSlug:
			typeof metadata.parent_slug === "string"
				? metadata.parent_slug
				: undefined,
		parentEntityType:
			typeof metadata.parent_entity_type === "string"
				? metadata.parent_entity_type
				: undefined,
		attribution:
			typeof metadata.attribution === "string"
				? metadata.attribution
				: undefined,
		proposerRationale:
			typeof metadata.proposer_rationale === "string"
				? metadata.proposer_rationale
				: undefined,
		initiator:
			metadata.initiator && typeof metadata.initiator === "object"
				? (metadata.initiator as RunInitiator)
				: undefined,
	};
}

function entityHrefFor(
	ownerSlug: string | null | undefined,
	details: Pick<
		EntityFieldChangeDetails,
		"entityType" | "entitySlug" | "parentEntityType" | "parentSlug"
	>,
) {
	if (!ownerSlug || !details.entityType || !details.entitySlug) return null;
	return buildEntityUrl(
		ownerSlug,
		details.parentEntityType && details.parentSlug
			? [
					{
						entity_type: details.parentEntityType,
						slug: details.parentSlug,
					},
					{ entity_type: details.entityType, slug: details.entitySlug },
				]
			: [{ entity_type: details.entityType, slug: details.entitySlug }],
	);
}

function WatcherApprovalHeader({
	runId,
	details,
}: {
	runId?: number;
	details: Pick<
		EntityFieldChangeDetails,
		"watcherId" | "watcherName" | "watcherAgentId" | "attribution" | "initiator"
	>;
}) {
	const { org } = useCurrentOrg();
	const watcherDetail = useWatcherDetail(
		details.watcherId,
		undefined,
		org?.id,
		{
			includeVersions: false,
		},
	);
	const watcher = watcherDetail.data?.behavior;
	// Not every proposal comes from a Behavior — agent-proposed changes carry no
	// watcher_id, so falling back to "Behavior" would misattribute them. The
	// recorded initiator names the actual agent when the proposal has one.
	const proposerFallback = proposerLabelFor(
		details.initiator,
		details.attribution,
		details.watcherId,
	);
	const watcherName =
		watcher?.behavior_name ?? details.watcherName ?? proposerFallback;
	const watcherAgentId = watcher?.agent_id ?? details.watcherAgentId ?? null;
	const ownerSlug = org?.slug;

	return (
		<div className="text-sm text-muted-foreground">
			Requested by{" "}
			{ownerSlug && watcherAgentId && details.watcherId ? (
				<Link
					to="/$owner/agents/$agentId/behaviors/$watcherId"
					params={{
