					className="font-medium text-foreground underline-offset-4 hover:underline"
				>
					{watcherName}
				</Link>
			) : (
				<span className="font-medium text-foreground">{watcherName}</span>
			)}
			{ownerSlug && runId && (
				<>
								onClick={() =>
									rejectRun.mutate(
										{ run_id: runId, reason: rejectReason || undefined },
										{
											// See the confirm handler above: the original permalink
											// now resolves to the full chain server-side, so no URL
											// rewrite is needed here either.
											onSuccess: () => {
												setResolved("rejected");
											},
										},
									)
								}
								disabled={rejectRun.isPending}
							>
								{rejectRun.isPending && <Spinner size="sm" className="mr-1" />}
								Confirm Reject
							</Button>
							<Button
								size="sm"
								variant="ghost"
								className="h-7 text-xs px-2"
								onClick={() => {
									setShowRejectInput(false);
									setRejectReason("");
								}}
							>
								Cancel
							</Button>
						</div>
					)}
				</div>
			)}
		</div>
	);
}

type ChangeSetEntry = {
	entityId: number;
	name: string;
	kind: "created" | "updated";
	applied: Record<string, { old: unknown; new: unknown }>;
};

/**
 * A watcher run's first-class change-set card: the created/updated summary and a
 * per-entity diff, shown on the run itself even when the changes were auto-applied
 * (no approval). When the run has a window and produced pending proposals, offers
 * a one-click Approve all / Reject with feedback (the batch + revision loop —
 * rejecting feeds the reason back so the user can ask the agent to revise). The
 * batch-reject feedback event renders the recorded reason instead.
 */
function RunChangeSetCard({ content }: { content: ContentItem }) {
	const metadata = (content.metadata || {}) as Record<string, unknown>;
	const kind = metadata.kind as string | undefined;
	const windowId =
		typeof metadata.window_id === "number" ? metadata.window_id : null;
	const watcherId =
		typeof metadata.window_id === "number" &&
		typeof metadata.watcher_id === "number"
			? metadata.watcher_id
			: typeof metadata.watcher_id === "number"
				? metadata.watcher_id
				: null;
	const { org } = useCurrentOrg();
	const ownerSlug = org?.slug;
	// Resolve the watcher so the card can name it (and link to its page) — a batch
	// card with no identity is impossible to tell apart from another run's card.
	const watcherDetail = useWatcherDetail(
		watcherId != null ? String(watcherId) : undefined,
		undefined,
		org?.id,
		{ includeVersions: false },
	);
	const watcher = watcherDetail.data?.behavior;
	const watcherName =
		watcher?.behavior_name ??
		(watcherId != null ? `Behavior ${watcherId}` : "A Behavior");
	const watcherAgentId = watcher?.agent_id ?? null;
	const approveBatch = useApproveBatch();
	const rejectBatch = useRejectBatch();
	const [showReject, setShowReject] = useState(false);
	const [reason, setReason] = useState("");
	const [resolved, setResolved] = useState<"approved" | "rejected" | null>(
		null,
	);

	// The batch-reject feedback record: show why the run's proposals were rejected.
	if (kind === "watcher_batch_reject") {
		const rejectReason = (metadata.reason as string | undefined) || undefined;
		return (
			<div className="rounded-md border border-destructive/40 bg-destructive/5 p-3">
				<div className="text-sm font-medium">Proposals rejected</div>
				{rejectReason && (
					<div className="mt-1 text-sm text-muted-foreground">
						{rejectReason}
					</div>
				)}
				<div className="mt-1 text-xs text-muted-foreground">
					Ask the agent to revise its proposals with this feedback.
				</div>
			</div>
		);
	}

	const changes = Array.isArray(metadata.changes)
		? (metadata.changes as ChangeSetEntry[])
		: [];
	const createdCount =
		typeof metadata.created_count === "number"
			? metadata.created_count
			: changes.filter((c) => c.kind === "created").length;
	const updatedCount =
		typeof metadata.updated_count === "number"
			? metadata.updated_count
			: changes.filter((c) => c.kind === "updated").length;
	const updatedChanges = changes.filter(
		(c) => c.kind === "updated" && Object.keys(c.applied || {}).length > 0,
	);
	// Live count of proposals still awaiting a decision for this window (stamped
	// server-side; the change_set event itself is permanent). Undefined for older
	// events without the field — treat as "show buttons" so nothing regresses.
	const pendingProposalCount =
		typeof metadata.pending_proposal_count === "number"
			? metadata.pending_proposal_count
			: null;
	// Show the batch controls only while proposals remain pending. This survives a
	// refresh (server-derived), unlike the local `resolved` state which only hides
	// them within the current session after a click.
	const hasPendingProposals =
		pendingProposalCount == null || pendingProposalCount > 0;

	// While proposals are still pending they are PROPOSED, not yet applied — say so.
	const summaryVerb = hasPendingProposals ? "proposed" : "applied";

	return (
		<div className="rounded-md border p-3">
			<div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1">
				<div className="text-sm font-medium">
					{summaryVerb === "proposed" ? "Proposed" : "Applied"} {createdCount}{" "}
					new + {updatedCount} updated

